import { loadTestWasm, ownedUtxos, testBalances, vectors } from "./fakes";
const PASSWORD = "correct horse battery";
const inputsOf = (cbor: string) => txInputs(Uint8Array.from(Buffer.from(cbor, "hex")));

describe("money#1: a stranger's copy of a box-minted Seedelf's datum, as found", () => {
  it("is never the next stealth mint's first pick while a box back from Lovejoin pays alone", { timeout: 120_000 }, async () => {
    const v = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
    const t = testBalances();
    await t.wallet.create(v.phrase, PASSWORD);
    await t.balances.get("preprod");
    const wasm = loadTestWasm();
    const fresh = () => t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
    const row = (txHash: string, txIndex: number, lovelace: string, datum: string, height: number, assets: KoiosUtxo["asset_list"] = []): KoiosUtxo => ({
      ...ownedUtxos[0]!, tx_hash: txHash, tx_index: txIndex, value: lovelace, asset_list: assets, inline_datum: { bytes: datum, value: null }, block_height: height });
    const boxBack = async (b: KoiosUtxo) => {
      const back: PendingTx = { kind: "lovejoin-withdraw", network: "preprod", txHash: b.tx_hash, submittedAt: t.clock.now, confirmations: null };
      await t.activity.sent("preprod", back, { lovelace: b.value });
    };
    // 1. Box B1 (5 ₳), then Seedelf #1 from the private balance: B15 takes the box.
    const b1 = row("b1".repeat(32), 0, "5000000", await fresh(), 9_000_001);
    await boxBack(b1); t.koios.added.push(b1); t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    const first = await t.mint.build("preprod", "one", "seedelf");
    expect(inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor)).toEqual([`${b1.tx_hash}#0`]);
    t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
    const sender = new MintService({ ...t.deps,
      wasm: { ...wasm, signScriptSpend: (_k: unknown, r: string) => JSON.stringify({ txCbor: JSON.parse(r).txCbor, txHash: first.txHash }) } as typeof wasm,
      collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch) });
    await sender.submit("preprod", first.txHash);
    t.koios.confirmations = 1; await t.pending.pending("preprod"); await t.pending.pending("preprod");
    const mintEntry = (await t.activity.seedelf("preprod")).find((e) => e.txHash === first.txHash);
    expect(mintEntry?.origin).toEqual(boxFrom(b1.tx_hash));
    // 2. It lands: Seedelf #1 under R1 with its token, its change; B1 gone. 3. Boxes B2, B3; the stranger's 4 ₳ under R1 (d = 1).
    const r1 = await fresh();
    const seedelfA = ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
    const seedelf1 = row(first.txHash, 0, first.lovelace, r1, 9_000_002, [{ ...seedelfA.asset_list![0]!, asset_name: first.tokenName, quantity: "1" }]);
    const change = row(first.txHash, 1, first.changeLovelace, await fresh(), 9_000_002);
    t.koios.added.splice(t.koios.added.indexOf(b1), 1); t.koios.spent.add(`${b1.tx_hash}#0`);
    const b2 = row("b2".repeat(32), 0, "5000000", await fresh(), 9_000_003);
    const b3 = row("b3".repeat(32), 0, "5000000", await fresh(), 9_000_003);
    await boxBack(b2); await boxBack(b3);
    const copy = row("c0".repeat(32), 0, "4000000", r1, 9_000_003);
    t.koios.added.push(seedelf1, change, b2, b3, copy); t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    const C = `${copy.tx_hash}#0`;
    const classes = await t.activity.classes("preprod", [copy, b2, b3, change], [...ownedUtxos, seedelf1, copy, b2, b3, change]);
    // 4. Seedelf #2 from the private balance.
    await t.mint.build("preprod", "two", "seedelf");
    const secondInputs = inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
    expect.soft(classes.get(C)?.origin, "the copy's class").not.toBe("lovejoin");
    expect(secondInputs, "Seedelf #2's mint inputs").not.toContain(C);
  });
});
