import { describe, expect, it } from "vitest";
import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { CHAIN_CUT, LovejoinService } from "../src/background/lovejoin";
import { SESSION_MINT } from "../src/background/mint";
import { CHAINS, HOUR, withSession, type Tested } from "./chain-fixtures";
import { preprodAddress } from "./fixtures/bech32";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, ownedUtxos } from "./fakes";
import { ADA, ADA_POOL, adaBox, ownDatum } from "./v2-pools";

const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));
const inAda = (txHash: string, txIndex = 0) => ({ txHash, txIndex, pool: ADA });
const inputsOf = (bytes: Uint8Array | string) => txInputs(typeof bytes === "string" ? Uint8Array.from(Buffer.from(bytes, "hex")) : bytes);

function witnessed(t: Tested, extra: Partial<ConstructorParameters<typeof LovejoinService>[0]> = {}) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  return new LovejoinService({
    ...t.deps,
    wasm: { ...wasm, finishLovejoinWithdraw: (request: string) => {
      const { txCbor } = JSON.parse(request) as { txCbor: string };
      return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
    } } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store, pools: async () => [ADA_POOL], ...extra,
  });
}
async function privateRow(t: Tested, txHash: string, lovelace: string): Promise<KoiosUtxo> {
  const wasm = loadTestWasm();
  const bytes = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  return { ...ownedUtxos[0]!, tx_hash: txHash, tx_index: 0, value: lovelace, asset_list: [], inline_datum: { bytes, value: null }, block_height: 9_000_001 };
}
async function bringBackAnyway(t: Tested, lj: LovejoinService, tx: string) {
  await lj.status("preprod");
  const back = await lj.withdrawNow("preprod", inAda(tx), true);
  const history = await t.store.get<{ entries: Array<{ txHash: string; kind: string; lovelace: string; origin?: unknown }> }>("history.preprod");
  const entry = history!.entries.find((e) => e.txHash === back.txHash)!;
  const spends = inputsOf(t.koios.submitted.at(-1)!);
  return { back, entry, spends, row: await privateRow(t, back.txHash, entry.lovelace) };
}

describe("chunk 51 calls round, money#3: a session's box not mixed yet, brought back anyway", CHAINS, () => {
  it("is never what a stealth mint takes first: its way back is the session's money, not a box back from a mix", async () => {
    const { t } = await withSession("40000000");
    await t.balances.get("preprod");
    const D = hash("96");
    const cut = { id: hash("97"), session: 0, progress: "seedelf.lovejoin.test", deposit: D, mixes: [hash("97")], leaves: [inAda(hash("97"))], boxes: 1, pools: { [ADA]: 1 }, total: 2, sent: 1, at: t.clock.now - 2 * HOUR, scheduled: true, stopped: CHAIN_CUT(), cut: true, ended: t.clock.now - 2 * HOUR };
    t.koios.addedToAccounts.push(adaBox(D, await ownDatum(t.wallet), t.clock.now));
    await t.store.set("lovejoin.preprod", { due: [], chains: [cut] });
    const lj = witnessed(t);
    expect((await lj.status("preprod")).pools!.find((p) => p.id === ADA)!.notMixed).toEqual([inAda(D)]);
    const { back, entry, spends, row } = await bringBackAnyway(t, lj, D);
    const W = `${back.txHash}#0`;
    console.log("[money#3] the way back spends", JSON.stringify(spends), "sealed origin", JSON.stringify(entry.origin ?? null), "lovelace", entry.lovelace);
    expect(spends).toContain(`${D}#0`);
    const bob = await privateRow(t, hash("b0"), "60000000");
    t.koios.added.push(row, bob);
    t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    const classes = await t.activity.classes("preprod", [row, bob]);
    console.log("[money#3] classes", JSON.stringify(Object.fromEntries(classes)));
    const minted = await t.mint.build("preprod", "", "seedelf");
    const mintInputs = inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
    console.log("[money#3] the stealth mint spends", JSON.stringify(mintInputs.map((i) => (i === W ? "the session's unmixed box, back" : i === `${bob.tx_hash}#0` ? "Bob's 60 ₳" : i))), "histories", JSON.stringify(minted.histories ?? null));
    expect.soft(classes.get(W)?.origin, "the way back's class").not.toBe("lovejoin");
    expect.soft(mintInputs, "the stealth mint's inputs").not.toContain(W);
  });

  it("the session's collateral's box, its mix never gone, comes back as the session's money too", async () => {
    const { t } = await withSession("40000000");
    const T = hash("d6");
    const chain = { id: hash("d8"), session: 0, progress: "seedelf.session.chain.preprod.0", deposit: hash("d1"), mixes: [hash("d2")], leaves: [inAda(hash("d2")), inAda(hash("d7"))],
      tail: { deposit: T, mix: hash("d7"), pool: ADA, box: inAda(T), leaf: inAda(hash("d7")), tries: 2, landed: t.clock.now - 30 * HOUR, over: true },
      boxes: 1, pools: { [ADA]: 2 }, total: 5, sent: 3, at: t.clock.now - 30 * HOUR, scheduled: true, stopped: CHAIN_CUT(), cut: true, ended: t.clock.now - 29 * HOUR };
    t.koios.addedToAccounts.push(adaBox(T, await ownDatum(t.wallet), t.clock.now));
    await t.store.set("lovejoin.preprod", { due: [], chains: [chain] });
    const lj = witnessed(t);
    expect((await lj.status("preprod")).pools!.find((p) => p.id === ADA)!.notMixed).toEqual([inAda(T)]);
    const { back, entry, spends, row } = await bringBackAnyway(t, lj, T);
    t.koios.added.push(row); t.clock.now += 60_000; await t.balances.get("preprod", true);
    const classes = await t.activity.classes("preprod", [row]);
    console.log("[money#3] tail: spends", JSON.stringify(spends), "sealed", JSON.stringify(entry.origin ?? null), "class", JSON.stringify(classes.get(`${back.txHash}#0`)));
    expect.soft(classes.get(`${back.txHash}#0`)?.origin, "the collateral's way back's class").not.toBe("lovejoin");
  });

  it("after a restore, a box one of the phrase's one-time keys deposited comes back as a session's money too", async () => {
    const { t } = await withSession("40000000");
    const A = hash("a7");
    const key = await t.wallet.withKeys((k) => k.oneTime.keyHash(0));
    t.koios.addedToAccounts.push(adaBox(A, await ownDatum(t.wallet), t.clock.now));
    t.koios.txSpends.set(A, [{ payment_addr: { bech32: preprodAddress(key), cred: key } }]);
    const lj = witnessed(t, { sessionIndices: async () => [0] });
    const status = (await lj.status("preprod")).pools!.find((p) => p.id === ADA)!;
    expect(status.notMixed).toEqual([inAda(A)]);
    expect(status.someoneElse ?? []).toEqual([]);
    const { back, entry, row } = await bringBackAnyway(t, lj, A);
    t.koios.added.push(row); t.clock.now += 60_000; await t.balances.get("preprod", true);
    const classes = await t.activity.classes("preprod", [row]);
    console.log("[money#3] restore: sealed", JSON.stringify(entry.origin ?? null), "class", JSON.stringify(classes.get(`${back.txHash}#0`)));
    expect.soft(classes.get(`${back.txHash}#0`)?.origin, "the restored deposit's way back's class").not.toBe("lovejoin");
  });
});
