import { builtOutputs } from "../src/background/minswap";
import { boxFrom } from "../src/shared/histories";
import type { PendingTx } from "../src/shared/rpc";
import { loadTestWasm, ownedUtxos, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const bytes = (h: string) => Uint8Array.from(Buffer.from(h, "hex"));
const inputsOf = (cbor: string) => txInputs(bytes(cbor));

async function wallet() {
  const v = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
  const t = testBalances();
  await t.wallet.create(v.phrase, PASSWORD);
  await t.balances.get("preprod");
  const wasm = loadTestWasm();
  const fresh = () => t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  const row = (txHash: string, txIndex: number, lovelace: string, datum: string, height: number, assets: KoiosUtxo["asset_list"] = []): KoiosUtxo => ({
    ...ownedUtxos[0]!, tx_hash: txHash, tx_index: txIndex, value: lovelace, asset_list: assets, inline_datum: { bytes: datum, value: null }, block_height: height,
  });
  const mintAndLand = async (label: string, height: number) => {
    const s = await t.mint.build("preprod", label, "seedelf");
    const kept = (await t.session.get<{ txCbor: string; origin?: unknown }>(SESSION_MINT))!;
    const spent = inputsOf(kept.txCbor);
    t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
    const signer = new MintService({
      ...t.deps,
      wasm: { ...wasm, signScriptSpend: (_k: unknown, r: string) => JSON.stringify({ txCbor: JSON.parse(r).txCbor, txHash: s.txHash }) } as typeof wasm,
      collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    });
    await signer.submit("preprod", s.txHash); // pending.ts:603 writes the history from the kept summary
    t.koios.confirmations = 1;
    await t.pending.pending("preprod");
    await t.pending.pending("preprod");
    for (const i of spent) { t.koios.added.splice(t.koios.added.findIndex((u) => `${u.tx_hash}#${u.tx_index}` === i), 1); t.koios.spent.add(i); }
    const made = builtOutputs(bytes(kept.txCbor)).map((o, i) => row(s.txHash, i, o.lovelace.toString(), o.datum!, height,
      o.tokens ? [{ policy_id: CONTRACT_V1.seedelfPolicyId, asset_name: s.tokenName, quantity: "1", decimals: 0, fingerprint: "" }] : []));
    const change = made.find((u) => !(u.asset_list ?? []).length)!;
    t.koios.added.push(...made);
    t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    return { spent, origin: kept.origin, change, C: `${change.tx_hash}#${change.tx_index}` };
  };
  const lastMintInputs = async () => inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
  return { t, fresh, row, mintAndLand, lastMintInputs };
}

describe("own#1: the change of a stealth mint", () => {
  it("a box paid for is not taken by the next stealth mint ahead of a payment received that pays alone", { timeout: 60_000 }, async () => {
    const { t, fresh, row, mintAndLand, lastMintInputs } = await wallet();
    const box = row("bb".repeat(32), 0, "10000000", await fresh(), 9_000_001);
    const back: PendingTx = { kind: "lovejoin-withdraw", network: "preprod", txHash: box.tx_hash, submittedAt: t.clock.now, confirmations: null };
    await t.activity.sent("preprod", back, { lovelace: box.value });
    const bob = row("b0".repeat(32), 0, "20000000", await fresh(), 9_000_001);
    t.koios.added.push(box, bob);
    t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    const s1 = await mintAndLand("s1", 9_000_002);
    expect(s1.spent).toEqual([`${box.tx_hash}#0`]); // (b), as decided
    const classes = await t.activity.classes("preprod", [s1.change, bob]);
    await t.mint.build("preprod", "s2", "seedelf");
    const s2 = await lastMintInputs();
    expect.soft(classes.get(s1.C), "S1's change is classed exactly as a box back from Lovejoin").not.toEqual(boxFrom(box.tx_hash));
    expect.soft(s2, "S2's inputs").not.toContain(s1.C);
  });

  it("Bob's payment paid for is not taken by the next stealth mint ahead of Carol's, which pays alone (the same gap, no box)", { timeout: 60_000 }, async () => {
    const { t, fresh, row, mintAndLand, lastMintInputs } = await wallet();
    const bob = row("b0".repeat(32), 0, "20000000", await fresh(), 9_000_001);
    const carol = row("c0".repeat(32), 0, "30000000", await fresh(), 9_000_001);
