use std::ops::Deref;
use pallas_codec::minicbor;
use pallas_primitives::{Fragment, conway};
use seedelf_wasm::decode::decode_tx;

fn tx(entries: &[(u64, &str)], witnesses: &str) -> String {
    let mut out = Vec::new();
    let mut e = minicbor::Encoder::new(&mut out);
    e.array(4).unwrap();
    e.map(entries.len() as u64).unwrap();
    for (key, value) in entries {
        e.u64(*key).unwrap();
        e.writer_mut().extend_from_slice(&hex::decode(value).unwrap());
    }
    e.writer_mut().extend_from_slice(&hex::decode(witnesses).unwrap());
    e.bool(true).unwrap();
    e.null().unwrap();
    hex::encode(out)
}
fn input(byte: &str, index: &str, open: bool) -> String {
    let id = byte.repeat(32);
    if open { format!("9f5820{id}{index}ff") } else { format!("825820{id}{index}") }
}
const OUTPUT: &str = "8182581d60a3d6d926176be50d7d03ecaf007932b670592111602201ae9c20d4381a001e8480";
const FEE: &str = "1a00030d40";
fn with_redeemers(two: bool, redeemers: &str) -> String {
    let inputs = if two { format!("82{}{}", input("11", "00", false), input("22", "01", false)) } else { format!("81{}", input("11", "00", false)) };
    tx(&[(0, &inputs), (1, OUTPUT), (2, FEE)], &format!("a105{redeemers}"))
}
fn pallas_redeemers(cbor: &str) -> usize {
    let bytes = hex::decode(cbor).unwrap();
    let tx = conway::MintedTx::decode_fragment(&bytes).expect("Pallas reads the transaction");
    match tx.transaction_witness_set.redeemer.as_ref().map(|r| r.deref().clone()) {
        Some(conway::Redeemers::Map(m)) => m.iter().count(),
        Some(conway::Redeemers::List(l)) => l.iter().count(),
        None => 0,
    }
}
fn shown(cbor: &str) -> Result<usize, String> {
    decode_tx("preprod", cbor).map(|d| d.redeemers.len()).map_err(|e| e.to_string())
}
#[test]
fn a_redeemer_key_written_open_length_is_read_as_pallas_and_the_ledger_read_it() {
    let definite = with_redeemers(false, "a18200008200820000");
    let open_key = with_redeemers(false, "a19f0000ff8200820000");
    assert_eq!(pallas_redeemers(&definite), 1);
    assert_eq!(pallas_redeemers(&open_key), 1, "Pallas reads [_ 0, 0] as the key");
    assert_eq!(shown(&definite), Ok(1));
