  LIST: ["abandon", "ability", "able", "about", "above", "absent", "absorb", "abstract", "absurd", "abuse", "access", "accident"],
}));

// The state of a person typing, which a server render can't reach by itself: the box has focus (WordBox's `focused`,
// and `touched`, start true) and the word list has come (useWordlist's state starts as the list).
vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  return {
    ...react,
    useState: (initial?: unknown) =>
      react.useState(initial === false ? true : Array.isArray(initial) && initial.length === 0 ? seam.LIST : initial),
  };
});

const { PhraseInput } = await import("../src/ui/components/PhraseInput");

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const VOID = new Set(["input", "br", "img", "hr", "meta", "link", "wbr"]);

/** Each suggestion (`<li role="option">`) as Translate would see it: its text, and whether it or an element around it is translate="no". */
function options(markup: string): Array<{ text: string; marked: boolean }> {
  const open: Array<{ tag: string; no: boolean; option?: { text: string; marked: boolean } }> = [];
  const out: Array<{ text: string; marked: boolean }> = [];
  for (const m of markup.matchAll(/<(\/?)([a-zA-Z0-9]+)([^>]*?)(\/?)>|([^<]+)/g)) {
    const [, closing, tag, attrs = "", selfClosing, text] = m;
    if (text !== undefined) {
      const inside = [...open].reverse().find((e) => e.option);
      if (inside?.option) inside.option.text += text;
      continue;
    }
    const name = tag!.toLowerCase();
    if (closing) {
      while (open.length && open.pop()!.tag !== name);
      continue;
    }
    if (selfClosing || VOID.has(name)) continue;
    const no = /\btranslate="no"/.test(attrs) || /\bnotranslate\b/.test(attrs);
    const entry: (typeof open)[number] = { tag: name, no };
    if (name === "li" && /\brole="option"/.test(attrs)) {
      entry.option = { text: "", marked: no || open.some((e) => e.no) };
      out.push(entry.option);
    }
    open.push(entry);
  }
  return out;
}

/** The three screens that type a phrase, each with its first typed box at "aba", and Create's confirm box at "abl". */
function typed(): Array<[string, string]> {
  const noop = () => undefined;
  const restore = ["aba", ...Array<string>(23).fill("")];
  const confirm = Array<string>(24).fill("");
  confirm[2] = "abl";
  return [
    ["Restore, and Settings' Check recovery phrase", renderToStaticMarkup(createElement(PhraseInput, { words: restore, onChange: noop, onCountChange: noop }))],
    ["Create's confirm words", renderToStaticMarkup(createElement(PhraseInput, { words: confirm, onChange: noop, positions: [3, 7, 11], wrong: [] }))],
  ];
}

describe("the recovery phrase typed, under Chrome's Translate (chunk 51's calls round, review docs#1)", () => {
  it("lists the phrase's own word as page text once three letters are typed", () => {
    const [[, restore], [, confirm]] = typed();
    expect(options(restore!).map((o) => o.text)).toEqual(["abandon"]);
    expect(options(confirm!).map((o) => o.text)).toEqual(["able"]);
  });

  it("and that list is marked not to translate, as the shown grid is", () => {
    for (const [screen, markup] of typed()) {
      expect({ screen, options: options(markup) }).toEqual({ screen, options: options(markup).map((o) => ({ ...o, marked: true })) });
    }
  });

  it("so the policy's word that Translate never gets the phrase holds where the phrase is typed too", () => {
    const policy = readFileSync(join(ROOT, "../docs/store/privacy-policy.md"), "utf8");
    const privacy = readFileSync(join(ROOT, "../docs/privacy.md"), "utf8");
    const promises = [
      /but not your recovery phrase/.test(policy),
      /Translate no longer gets your recovery phrase/.test(policy),
      /recovery phrase's 24 words are kept out/.test(privacy),
    ];
    if (!promises.some(Boolean)) return;
    const unmarked = typed().flatMap(([screen, markup]) => options(markup).filter((o) => !o.marked).map((o) => `${screen}: ${o.text}`));
    expect({ promises, unmarked }).toEqual({ promises, unmarked: [] });
  });
});
