// Chunk 51's calls round, docs#7. seedelf-verification/test-tools.sh holds the proofs' tools to their rules on fake
// packages, with no Lean or Lake, in about ten seconds: check.sh, and since this round its EXPECTED verdict
// (expected-failures.txt), tally.py, Audit/count.py, Audit/run-all.sh and the diag scan with its accepted list
// (Audit/diag/accepted.txt). The round grew it from 50 checks to 80, and it reads Seedelf/PolicyBurn.lean and
// PolicyMint.lean against a console recorded by line and column. web-wallet.yml's covered filter leaves
// seedelf-verification/ out, so the proofs' pull requests stay fast, and no other workflow ran the script: a pull
// request that changed only one of those files merged with no check. So a workflow runs it on every pull request that
// changes the script or a file it reads.
describe("the proofs' tools' own test", () => {
  const VERIFICATION = fileURLToPath(new URL("../../../../seedelf-verification/", import.meta.url));
  const escape = (s: string) => s.replace(/[.+?^${}()|[\]\\]/g, "\\$&");

  /** The script and each file it reads from its folder (`$TOOLS/…`, a glob expanded), and the diag scan's
   * accepted.txt, which the scan reads beside itself, from the repository's root. */
  function read(): string[] {
    const text = readFileSync(join(VERIFICATION, "test-tools.sh"), "utf8");
    const found = new Set(["test-tools.sh", "Audit/diag/accepted.txt"]);
    for (const [, path] of text.matchAll(/"?\$TOOLS"?\/([\w./*-]+)/g)) {
      const slash = path!.lastIndexOf("/");
      const folder = slash < 0 ? "" : path!.slice(0, slash);
      const name = path!.slice(slash + 1);
      if (!name.includes("*")) {
        found.add(path!);
        continue;
      }
      const re = new RegExp(`^${name.split("*").map(escape).join("[^/]*")}$`);
      for (const f of readdirSync(join(VERIFICATION, folder))) if (re.test(f)) found.add(`${folder}/${f}`);
    }
    return [...found].map((f) => `seedelf-verification/${f}`).sort();
  }

  /** GitHub's paths syntax: `**` any characters, `*` any but `/`. */
  function glob(pattern: string): RegExp {
    let re = "";
    for (let i = 0; i < pattern.length; i++) {
      if (pattern.startsWith("**/", i)) {
        re += "(?:.*/)?";
        i += 2;
      } else if (pattern.startsWith("**", i)) {
        re += ".*";
        i += 1;
      } else re += pattern[i] === "*" ? "[^/]*" : escape(pattern[i]!);
    }
    return new RegExp(`^${re}$`);
  }

  /** Whether a pull request that changes only `path` starts the workflow: pull_request in its `on:`, with no paths
   * filter, or one that takes the path (the last pattern that matches wins, `!` leaving it out). */
  function startsOn(lines: string[], path: string): boolean {
    const at = lines.findIndex((line) => /^on:/.test(line));
    if (at < 0) return false;
    const inline = /^on:\s*([^#]*)/.exec(lines[at]!)?.[1]?.trim();
    if (inline) return /\bpull_request\b/.test(inline);
    const body = under(lines, at);
    const pr = body.findIndex((line) => /^\s+pull_request:/.test(line));
    if (pr < 0) return false;
    const filter = under(body, pr);
    const list = (key: string) => {
      const k = filter.findIndex((line) => new RegExp(`^\\s+${key}:`).test(line));
      if (k < 0) return null;
      return under(filter, k)
        .filter((line) => !blank(line))
        .map((line) => line.trim().replace(/^-\s*/, "").replace(/^["']|["']$/g, ""));
    };
    const paths = list("paths");
    if (paths) {
      let hit = false;
      for (const p of paths) {
        if (p.startsWith("!")) {
          if (glob(p.slice(1)).test(path)) hit = false;
        } else if (glob(p).test(path)) hit = true;
      }
      return hit;
    }
    const ignored = list("paths-ignore");
    return !(ignored ?? []).some((p) => glob(p).test(path));
  }

  it("runs on every pull request that changes the script or a file it reads", () => {
    const files = read();
    // Not vacuous: the files this round's verdicts live in, and the two sources read by line and column.
    expect(files).toEqual(
      expect.arrayContaining([
        "seedelf-verification/check.sh",
        "seedelf-verification/expected-failures.txt",
        "seedelf-verification/Audit/diag/scan-diag.py",
        "seedelf-verification/Audit/diag/accepted.txt",
        "seedelf-verification/Seedelf/PolicyBurn.lean",
        "seedelf-verification/Seedelf/PolicyMint.lean",
      ]),
    );
    const all = workflows();
    const lines = (file: string) => all.find((w) => w.file === file)?.lines ?? [];
    // Not vacuous: the triggers read as GitHub reads them.
    expect(startsOn(lines("data-layer.yml"), "seedelf-data/api/src/main.rs")).toBe(true);
    expect(startsOn(lines("data-layer.yml"), "seedelf-verification/check.sh")).toBe(false);
    expect(startsOn(lines("release.yml"), "seedelf-verification/check.sh")).toBe(false);
    expect(startsOn(lines("continuous-integration.yml"), "seedelf-verification/check.sh")).toBe(true);

    // The workflows with a step whose script runs test-tools.sh.
    const running = [
      ...new Set(
        scripts()
          .filter(({ lines }) => lines.some((line) => !comment(line) && /\btest-tools\.sh\b/.test(line)))
          .map(({ where }) => where.split(":")[0]!),
      ),
    ];
    const untested = files.filter((path) => !running.some((file) => startsOn(lines(file), path)));
    expect({ running, untested }).toEqual({ running: expect.arrayContaining([expect.any(String)]), untested: [] });
  });
});
